import React from 'react';
import { Image, type ImageStyle, type StyleProp } from 'react-native';
import manifest from '../../../assets/paper/manifest.json';

/**
 * The collage's loose paper: torn shapes generated by scripts/paper-art.mjs, used as art (onboarding
 * backdrops, empty states). Each is a WebP with its own soft shadow and white core baked in, so it is laid
 * on the page as it is — never tinted, never outlined.
 *
 * `w` is the width in dp; the height keeps the piece's own proportions (the generator's manifest).
 */
const SRC = {
  dot: require('../../../assets/paper/art-dot.webp'),
  'hill-sage': require('../../../assets/paper/art-hill-sage.webp'), 'hill-moss': require('../../../assets/paper/art-hill-moss.webp'),
  'strip-kraft': require('../../../assets/paper/art-strip-kraft.webp'), 'strip-denim': require('../../../assets/paper/art-strip-denim.webp'),
  'scrap-cream': require('../../../assets/paper/art-scrap-cream.webp'), 'scrap-sky': require('../../../assets/paper/art-scrap-sky.webp'),
  'scrap-sand': require('../../../assets/paper/art-scrap-sand.webp'), 'scrap-sage': require('../../../assets/paper/art-scrap-sage.webp'),
  leaf: require('../../../assets/paper/art-leaf.webp'), 'leaf-sage': require('../../../assets/paper/art-leaf-sage.webp'),
  ruled: require('../../../assets/paper/art-ruled.webp'), 'ruled-wide': require('../../../assets/paper/art-ruled-wide.webp'), tape: require('../../../assets/paper/art-tape.webp'), 'disc-denim': require('../../../assets/paper/art-disc-denim.webp'),
} as const;
export type ArtName = keyof typeof SRC;

const ratio = (n: ArtName) => { const m = (manifest as Record<string, { w: number; h: number }>)[`art-${n}`]; return m ? m.h / m.w : 1; };

export function Art({ name, w, rot = 0, style }: { name: ArtName; w: number; rot?: number; style?: StyleProp<ImageStyle> }) {
  return <Image fadeDuration={0} source={SRC[name]} accessible={false} importantForAccessibility="no" style={[{ width: w, height: w * ratio(name), transform: rot ? [{ rotate: `${rot}deg` }] : undefined }, style]} />;
}
